  expect(store.get(a, shared.id)).toBeNull();
  expect(store.history(a, shared.id)).toEqual([]);
  expect(() => store.archive(a, shared.id)).toThrow();
  store.archive(null, shared.id);
  expect(store.search(null, "SQLite", 10, "shared")).toEqual([]);
