import { expect, test } from "bun:test";
import { existsSync, statSync, symlinkSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { openWorkspaceDatabase } from "./workspace-database";
import { openDatabase } from "./connection";
import { withDirectory } from "../__test-support__/fixtures";

test("workspace creation produces private SQLite storage and never replaces a missing configured database", () => withDirectory(dir => {
  const path = join(dir, "db");
  expect(() => openWorkspaceDatabase(path, false, false, openDatabase)).toThrow(expect.objectContaining({ code: "DATABASE_MISSING" }));
  expect(existsSync(path)).toBe(false);
  const db = openWorkspaceDatabase(path, true, false, openDatabase);
  try { expect(db.query("SELECT count(*) AS n FROM projects").get()).toEqual({ n: 0 }); }
  finally { db.close(); }
  expect(statSync(path).mode & 0o777).toBe(0o600);
}));

test("unsafe sidecars are rejected before SQLite can touch their targets", () => withDirectory(dir => {
  const target = join(dir, "target"), path = join(dir, "db");
  writeFileSync(target, "private"); symlinkSync(target, path + "-wal");
  expect(() => openWorkspaceDatabase(path, true, false, openDatabase)).toThrow(expect.objectContaining({ code: "DATABASE_PATH_UNSAFE" }));
  expect(existsSync(path)).toBe(false);
}));

import { closeSync, lstatSync, openSync } from "node:fs";
import { MemoryError } from "../../shared/errors";

function existsAsOwnedFile(path: string): boolean {
  try {
    const stat = lstatSync(path);
    if (!stat.isFile() || stat.isSymbolicLink() || stat.nlink !== 1 ||
      (typeof process.getuid === "function" && stat.uid !== process.getuid())) {
      throw new MemoryError("DATABASE_PATH_UNSAFE", "La base o un archivo auxiliar tiene un enlace, propietario o tipo no permitido. No se abrió SQLite.");
    }
    return true;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return false;
    throw error;
  }
}

/** Called only after the private workspace root has been validated. */
export function openWorkspaceDatabase<T>(path: string, create: boolean, readonly: boolean, open: (path: string, options: { create: boolean; readonly: boolean }) => T): T {
  // Validate sidecars too: SQLite may open them as part of normal journal handling.
  for (const suffix of ["-wal", "-shm", "-journal"]) existsAsOwnedFile(path + suffix);
  const exists = existsAsOwnedFile(path);
  if (!exists && !create) throw new MemoryError("DATABASE_MISSING", "Falta la base configurada. No se creó un reemplazo; conserva la configuración y recupera tu base.");
  if (!exists) {
    try { closeSync(openSync(path, "wx", 0o600)); }
    catch (error) {
      // Another initializer can win the exclusive creation race. Never truncate.
      if ((error as NodeJS.ErrnoException).code !== "EEXIST") throw error;
    }
    existsAsOwnedFile(path);
  }
  return open(path, { create, readonly });
}

