import { MEMORY_PROTOCOL } from "./protocol";
import type { ClientId } from "./catalog";
export const RECOVERY="After compaction or resuming, recover the known conversation sessionId; never invent a replacement. Call memory_current_project and memory_context, then memory_search for previews and memory_get before relying on details. Hooks are reminders, not guaranteed model obedience.";
export function shellQuote(value:string):string{return `'${value.replaceAll("'","'\''")}'`;}
export function hookConfiguration(client:ClientId,executable:string):Record<string,unknown>{if(client==="opencode")return{};const command=`${shellQuote(executable)} memory-hook --client ${client}`;if(client==="cursor")return{sessionStart:[{command,timeout:3}]};const events=client==="gemini-cli"?["SessionStart","BeforeAgent"]:["SessionStart","UserPromptSubmit"];return Object.fromEntries(events.map(event=>[event,[{hooks:[{type:"command",...(client==="gemini-cli"?{name:"forge614-engram"}:{}),command,timeout:client==="gemini-cli"?3000:3}]}]]));}
export function createOpenCodePlugin():string{return `// Owned by Forge614 Engram. Embedded protocol; no runtime dependencies.
const protocol = ${JSON.stringify(MEMORY_PROTOCOL)};
const recovery = ${JSON.stringify(RECOVERY)};
export default async function Forge614Engram() {
  return {
    "experimental.chat.system.transform": async (_input, output) => {
      if (!Array.isArray(output.system)) return;
      if (output.system.some(entry => typeof entry === "string" && entry.includes(protocol))) return;
      if (output.system.length === 0) output.system.push(protocol);
      else if (typeof output.system[0] === "string") output.system[0] += "\n\n" + protocol;
    },
    "experimental.session.compacting": async (_input, output) => {
      if (Array.isArray(output.context) && !output.context.includes(recovery)) output.context.push(recovery);
    },
  };
}
`;}

