function date(v: unknown) { text(v); if(!/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d\.\d{3}Z$/.test(v) || !Number.isFinite(Date.parse(v))) syncError(); }
function keys(v: unknown, expected: string): asserts v is Record<string, any> {
